 const [feature,setFeature]=useState(0),[zoneIdx,setZoneIdx]=useState(0),[funcIdx,setFuncIdx]=useState(0),[qty,setQty]=useState(2),[date,setDate]=useState(''),[month,setMonth]=useState('2026-11');
 const [picker,setPicker]=useState(null),[menu,setMenu]=useState(false),[cityModal,setCityModal]=useState(false),[requestOpen,setRequestOpen]=useState(false),[requestCart,setRequestCart]=useState(false);
 const [selectedId,setSelectedId]=useState(null),[delivery,setDelivery]=useState('digital'),[now,setNow]=useState(Date.now()),[videoOpen,setVideoOpen]=useState(false),[filterWallet,setFilterWallet]=useState('todos');
 const video=useVideoPlayer(require('./assets/tadaa-video-demo.mp4'),p=>{p.loop=true});
 useEffect(()=>{(async()=>{try{const stored=await AsyncStorage.getItem('tadaa-v05-mobile');if(stored){const x=JSON.parse(stored);setFavorites(x.favorites||[]);setCart(x.cart||[]);setOrders(x.orders||[]);setProfile(x.profile||{name:'',email:'',phone:'',company:''});setCity(x.city||'Todas las ciudades');setMemberActive(!!x.memberActive)}}catch(e){console.log('Storage demo',e)}finally{setLoaded(true)}})()},[]);
 useEffect(()=>{if(!loaded)return;AsyncStorage.setItem('tadaa-v05-mobile',JSON.stringify({favorites,cart,orders,profile,city,memberActive})).catch(()=>{})},[loaded,favorites,cart,orders,profile,city,memberActive]);
