 const createOrder=(e,z,quantity,func)=>({id:'TD-'+Math.random().toString(36).slice(2,8).toUpperCase(),eventId:e.id,function:func,zone:z[0],qty:quantity,total:z[2]*quantity,status:'pending',expiresAt:0,createdAt:Date.now()});
 const submitRequest=()=>{if(profile.name.trim().length<3||!profile.email.includes('@')||profile.phone.replace(/\D/g,'').length<10||profile.company.length<2){Alert.alert('Faltan datos','Completa nombre, correo, WhatsApp y empresa con convenio.');return}
  if(requestCart){const newOrders=cart.map(x=>{const e=getEvent(x.eventId);return createOrder(e,e.zones[x.zoneIdx],x.qty,x.function)});if(!newOrders.length)return;setOrders(o=>[...o,...newOrders]);setCart([]);setFilterWallet('todos');setPage('wallet')}
  else{const func=chosenFunction();if(!func){Alert.alert('Selecciona la fecha');return}const o=createOrder(event,zone,qty,func);setOrders(old=>[...old,o]);setSelectedId(o.id);setPage('pase')}
  setRequestOpen(false)
 };
