 const Card=({e})=><TouchableOpacity style={s.card} onPress={()=>openEvent(e.id)}><Image source={IMAGES[e.id]} style={s.cardImage}/><View style={s.cardShade}/><View style={s.cardTag}><Pill text={e.cat}/></View><TouchableOpacity onPress={()=>fav(e.id)} style={s.cardHeart}>{icon(favorites.includes(e.id)?'heart':'heart-outline',21,favorites.includes(e.id)?L:WHITE)}</TouchableOpacity><View style={s.cardBody}><Text style={s.cardTitle} numberOfLines={2}>{e.title}</Text><Text style={s.cardCaption}>{e.city} · {e.date}</Text><View style={s.cardFoot}><Text style={s.cardFrom}>DESDE　<Text style={s.cardPrice}>{money(Math.min(...e.zones.map(z=>z[2])))}</Text></Text></View></View></TouchableOpacity>;
