  const info=regPostal[signup.postalCode],born=new Date((signup.dob||'')+'T12:00:00'),today=new Date(),age=today.getFullYear()-born.getFullYear()-(today.getMonth()<born.getMonth()||(today.getMonth()===born.getMonth()&&today.getDate()<born.getDate())?1:0),errors={};
  if(!info)errors.postalCode='Utiliza 06700, 03810 o 03100 en la demo.';
